-- =============================================================================
-- PDI · 0038 · Motor Alpha: coeficientes y plano de valor agregado
--
-- Ajusta el modelo publicado sobre los resultados ya cargados (0036) y guarda,
-- por año, programa y competencia, el puntaje esperado, el real, el valor
-- agregado, el plano y los cuadrantes frente a los promedios nacionales.
--
--   León FJ., Tobar Sánchez JA., González Calderón W., Suárez Arias RE.
--   "Analysis of generic competencies using a Linear Regression Model: A case
--   study in short-cycle programs". Innovaciencia 2025; 13(1): e4589.
--   http://dx.doi.org/10.15649/2346075X.4589 · CC BY-NC 4.0
--
-- Los coeficientes salen por mínimos cuadrados sobre los evaluados con las dos
-- pruebas completas. Se guardan los dos ajustes de cada competencia: el del
-- artículo (cinco competencias del Saber 11) y el ampliado (sin ciencias
-- naturales), que cubre a muchos más estudiantes. Las cifras por programa usan
-- el ampliado, y la ficha deja ver los dos.
--
-- Los promedios nacionales de referencia son los del artículo (Saber 11
-- 2014-2020 y Saber TyT 2016-2023); la intranet los puede cambiar.
--
-- Requiere 0036 y 0037. Idempotente.
-- =============================================================================

update public.od_saber_tyt t
set alpha = '{"modelos": {"cc": {"ampliado": {"coef": {"ing": -0.078, "intercepto": 30.026, "lc": 0.31, "m": 0.166, "sc": 1.015}, "n": 1079, "r2": 0.208, "rmse": 22.28}, "completo": {"coef": {"cn": 0.571, "ing": -0.129, "intercepto": 0.566, "lc": 0.531, "m": -0.095, "sc": 0.938}, "n": 409, "r2": 0.287, "rmse": 22.17}}, "ce": {"ampliado": {"coef": {"ing": -0.09, "intercepto": 78.626, "lc": 0.101, "m": 0.161, "sc": 0.28}, "n": 1016, "r2": 0.029, "rmse": 21.51}, "completo": {"coef": {"cn": 0.224, "ing": -0.18, "intercepto": 64.811, "lc": 0.248, "m": 0.29, "sc": 0.059}, "n": 375, "r2": 0.059, "rmse": 20.74}}, "global": {"ampliado": {"coef": {"ing": 0.143, "intercepto": 43.323, "lc": 0.201, "m": 0.302, "sc": 0.5}, "n": 1081, "r2": 0.253, "rmse": 14.98}, "completo": {"coef": {"cn": 0.509, "ing": 0.189, "intercepto": 19.204, "lc": 0.344, "m": 0.135, "sc": 0.289}, "n": 411, "r2": 0.371, "rmse": 13.86}}, "ing": {"ampliado": {"coef": {"ing": 1.179, "intercepto": 30.877, "lc": 0.185, "m": -0.007, "sc": 0.193}, "n": 1072, "r2": 0.354, "rmse": 18.31}, "completo": {"coef": {"cn": 0.224, "ing": 1.234, "intercepto": 10.289, "lc": 0.302, "m": -0.134, "sc": 0.205}, "n": 407, "r2": 0.454, "rmse": 16.97}}, "lc": {"ampliado": {"coef": {"ing": 0.046, "intercepto": 35.695, "lc": 0.367, "m": 0.321, "sc": 0.612}, "n": 1081, "r2": 0.199, "rmse": 20.62}, "completo": {"coef": {"cn": 0.615, "ing": 0.113, "intercepto": 16.469, "lc": 0.569, "m": -0.019, "sc": 0.296}, "n": 411, "r2": 0.26, "rmse": 19.45}}, "rc": {"ampliado": {"coef": {"ing": -0.315, "intercepto": 45.941, "lc": 0.073, "m": 0.873, "sc": 0.389}, "n": 1081, "r2": 0.187, "rmse": 21.14}, "completo": {"coef": {"cn": 0.787, "ing": -0.363, "intercepto": 14.09, "lc": 0.118, "m": 0.93, "sc": -0.021}, "n": 411, "r2": 0.329, "rmse": 18.47}}}, "nacional": {"saber11": {"cn": 56, "global": 285, "ing": 61, "lc": 58, "m": 57, "sc": 55}, "tyt": {"cc": 96, "ce": 94, "global": 95, "ing": 100, "lc": 97, "rc": 90}}}'::jsonb
from public.od_reports r
where r.id = t.report_id and r.slug = 'ensenanza' and t.key = 'saber-tyt';

