set alpha_n = v.alpha_n,
    alpha_expected = v.alpha_expected,
    alpha_actual = v.alpha_actual,
    alpha_va = v.alpha_va,
    alpha_positive = v.alpha_positive,
    plane = v.plane::jsonb,
    quadrants = v.quadrants::jsonb
